import Foundation
import PilotVisualsHost
import PilotVisualsKit
import Testing

/// The service must reproduce the kernel's pre-check exactly: packages/protocol/fixtures/visual/conformance.json,
/// generated by the kernel with quickjs-wasi, run here through the native engine and the shared runtime.js.
struct VisualConformanceTests {
    static let repository = URL(filePath: #filePath).deletingLastPathComponent().appending(path: "../../../..")
        .standardizedFileURL

    static func fixture() throws -> (runtime: String, cases: [String: Any]) {
        let runtime = try String(
            contentsOf: repository.appending(path: "packages/artifacts/src/visual/runtime.js"), encoding: .utf8)
        let data = try Data(contentsOf: repository.appending(path: "packages/protocol/fixtures/visual/conformance.json"))
        return (runtime, try #require(JSONSerialization.jsonObject(with: data) as? [String: Any]))
    }

    static func json(_ value: Any?) throws -> Data {
        try JSONSerialization.data(withJSONObject: value ?? NSNull(), options: [.fragmentsAllowed])
    }

    @Test func fixturesComeFromTheVendoredEngine() throws {
        #expect(try Self.fixture().cases["engine"] as? String == "quickjs-ng \(VisualHost.engineVersion)")
    }

    @Test(.timeLimit(.minutes(1))) func casesRenderTheKernelsTrees() async throws {
        let (runtime, fixture) = try Self.fixture()
        let cases = try #require(fixture["cases"] as? [[String: Any]])
        #expect(!cases.isEmpty)
        let host = VisualHost()
        for (index, item) in cases.enumerated() {
            let name = item["name"] as? String ?? "case \(index)"
            let request = VisualLoadRequest(
                runtime: runtime, source: try #require(item["source"] as? String), data: try Self.json(item["data"]),
                state: (item["state"] as? String).map { Data($0.utf8) },
                seed: try #require(item["id"] as? String),
                now: try #require((item["now"] as? NSNumber)?.doubleValue)
            )
            let id = "case\(index)"
            var last: VisualFrame?
            for (step, expected) in try #require(item["steps"] as? [[String: Any]]).enumerated() {
                let result: Result<VisualFrame, VisualFailure>
                if let event = expected["event"] as? [String: Any] {
                    result = await host.event(id, try #require(event["id"] as? String),
                                              try VisualValue(json: Self.json(event["value"])))
                } else {
                    result = await host.load(id, request)
                }
                guard case .success(let frame) = result else {
                    Issue.record("\(name) step \(step): \(result)")
                    break
                }
                let tree = try VisualValue(json: Self.json(expected["tree"]))
                // Through JSON on both sides, so key order (which Foundation drops) doesn't count.
                #expect(try VisualValue(json: frame.tree.jsonData) == tree, "\(name) step \(step)")
                if let changed = expected["changed"] as? [String] {
                    #expect(frame.changed == changed, "\(name) step \(step)")
                }
                last = frame
            }
            if let finalState = item["finalState"] as? String {
                #expect(last.map { String(decoding: $0.state, as: UTF8.self) } == finalState, "\(name)")
            }
            host.release(id)
        }
    }

    @Test(.timeLimit(.minutes(1))) func errorsReadLikeTheKernels() async throws {
        let (runtime, fixture) = try Self.fixture()
        let errors = try #require(fixture["errors"] as? [[String: Any]])
        #expect(!errors.isEmpty)
        let host = VisualHost()
        for (index, item) in errors.enumerated() {
            let name = item["name"] as? String ?? "error \(index)"
            let request = VisualLoadRequest(runtime: runtime, source: try #require(item["source"] as? String),
                                            data: try Self.json(item["data"]), seed: "", now: 0)
            let id = "error\(index)"
            var result = await host.load(id, request)
            for event in item["events"] as? [[String: Any]] ?? [] {
                guard case .success = result else { break }
                result = await host.event(id, try #require(event["id"] as? String),
                                          try VisualValue(json: Self.json(event["value"])))
            }
            guard case .failure(let failure) = result else {
                Issue.record("\(name): expected an error")
                continue
            }
            #expect(failure.message == item["error"] as? String, "\(name)")
            host.release(id)
        }
    }
}
